// Command shimgen generates the compatibility surface for the root Avro and OCF packages.
package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"go/format"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/mod/modfile"
	"golang.org/x/tools/go/packages"
)

const upstreamModulePath = "github.com/iskorotkov/avro/v2"

type target struct {
	importPath  string
	packageName string
	outputPath  string
}

type declarationSet struct {
	types     []string
	constants []string
	functions []string
	variables []string
}

func main() {
	check := flag.Bool("check", false, "verify generated files without changing them")
	flag.Parse()
	if flag.NArg() != 0 {
		fmt.Fprintln(os.Stderr, "usage: shimgen [-check]")
		os.Exit(2)
	}
	if err := run(*check); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(check bool) error {
	root, version, err := moduleRootAndVersion()
	if err != nil {
		return err
	}
	targets := []target{
		{importPath: upstreamModulePath, packageName: "avro", outputPath: filepath.Join(root, "avro_shim.go")},
		{importPath: upstreamModulePath + "/ocf", packageName: "ocf", outputPath: filepath.Join(root, "ocf", "ocf_shim.go")},
	}
	for _, target := range targets {
		generated, err := render(target, version)
		if err != nil {
			return err
		}
		if check {
			if err := checkOutput(target.outputPath, generated); err != nil {
				return err
			}
			continue
		}
		if err := writeAtomic(target.outputPath, generated); err != nil {
			return err
		}
	}
	return nil
}

func checkOutput(path string, generated []byte) error {
	current, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("generated Avro shim %s is missing: %w", path, err)
	}
	if !bytes.Equal(current, generated) {
		return fmt.Errorf("generated Avro shim %s is stale; run just avro-shim-generate", path)
	}
	return nil
}

func moduleRootAndVersion() (string, string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", "", err
	}
	root := cwd
	for {
		data, readErr := os.ReadFile(filepath.Join(root, "go.mod"))
		if readErr == nil {
			parsed, parseErr := modfile.Parse("go.mod", data, nil)
			if parseErr != nil {
				return "", "", fmt.Errorf("parse shim go.mod: %w", parseErr)
			}
			if parsed.Module == nil {
				return "", "", errors.New("shim go.mod has no module directive")
			}
			if parsed.Module.Mod.Path != "github.com/hamba/avro/v2" {
				return "", "", fmt.Errorf("found unrelated module %q while locating Avro shim", parsed.Module.Mod.Path)
			}
			for _, requirement := range parsed.Require {
				if requirement.Mod.Path == upstreamModulePath {
					if requirement.Mod.Version == "" {
						return "", "", errors.New("patched Avro requirement has no version")
					}
					return root, requirement.Mod.Version, nil
				}
			}
			return "", "", fmt.Errorf("shim go.mod does not require %s", upstreamModulePath)
		}
		parent := filepath.Dir(root)
		if parent == root {
			return "", "", errors.New("could not locate hamba Avro shim go.mod")
		}
		root = parent
	}
}

func render(target target, version string) ([]byte, error) {
	loaded, err := packages.Load(&packages.Config{Mode: packages.NeedName | packages.NeedTypes | packages.NeedImports | packages.NeedDeps | packages.NeedModule}, target.importPath)
	if err != nil {
		return nil, fmt.Errorf("load %s: %w", target.importPath, err)
	}
	if packages.PrintErrors(loaded) != 0 || len(loaded) != 1 || loaded[0].Types == nil {
		return nil, fmt.Errorf("load %s: package has type errors", target.importPath)
	}
	if loaded[0].Module == nil || loaded[0].Module.Path != upstreamModulePath || loaded[0].Module.Version != version {
		return nil, fmt.Errorf("load %s: resolved module is not %s@%s", target.importPath, upstreamModulePath, version)
	}
	declarations, fingerprint, err := inspectPackage(loaded[0].Types)
	if err != nil {
		return nil, fmt.Errorf("inspect %s: %w", target.importPath, err)
	}

	var output strings.Builder
	fmt.Fprintln(&output, "// Code generated by go run ./cmd/shimgen. DO NOT EDIT.")
	fmt.Fprintf(&output, "// Generated from %s@%s exported API.\n", upstreamModulePath, version)
	fmt.Fprintf(&output, "// Exported API SHA-256: %s.\n", fingerprint)
	fmt.Fprintln(&output, "// See third_party/hamba-avro-shim/README.md for provenance and regeneration details.")
	fmt.Fprintf(&output, "package %s\n\n", target.packageName)
	fmt.Fprintf(&output, "import upstream %q\n", target.importPath)
	emitSection(&output, "Types (aliases preserve type identity with the upstream module).", "type", declarations.types)
	emitSection(&output, "Constants.", "const", declarations.constants)
	emitSection(&output, "Functions (forwarded as function values; upstream defines the implementation).", "var", declarations.functions)
	emitSection(&output, "Variables (initialization-time snapshots; assignments do not propagate upstream).", "var", declarations.variables)
	formatted, err := format.Source([]byte(output.String()))
	if err != nil {
		return nil, fmt.Errorf("format %s shim: %w", target.packageName, err)
	}
	return formatted, nil
}

func inspectPackage(pkg *types.Package) (declarationSet, string, error) {
	var declarations declarationSet
	var api []string
	scope := pkg.Scope()
	for _, name := range scope.Names() {
		if !token.IsExported(name) {
			continue
		}
		object := scope.Lookup(name)
		switch typed := object.(type) {
		case *types.TypeName:
			if typeParameterCount(typed.Type()) != 0 {
				return declarationSet{}, "", fmt.Errorf("exported generic type %s cannot be represented by a plain type alias", name)
			}
			declarations.types = append(declarations.types, name)
			api = append(api, "type "+name+" "+canonicalType(typed.Type())+" underlying "+canonicalType(typed.Type().Underlying()))
			api = append(api, exportedMethods(name, typed.Type())...)
		case *types.Const:
			declarations.constants = append(declarations.constants, name)
			api = append(api, "const "+name+" "+canonicalType(typed.Type())+" = "+typed.Val().ExactString())
		case *types.Func:
			signature, ok := typed.Type().(*types.Signature)
			if !ok {
				return declarationSet{}, "", fmt.Errorf("exported function %s has unexpected type %T", name, typed.Type())
			}
			if signature.TypeParams() != nil && signature.TypeParams().Len() != 0 {
				return declarationSet{}, "", fmt.Errorf("exported generic function %s cannot be represented by a function-value forwarder", name)
			}
			declarations.functions = append(declarations.functions, name)
			api = append(api, "func "+name+" "+canonicalType(signature))
		case *types.Var:
			declarations.variables = append(declarations.variables, name)
			api = append(api, "var "+name+" "+canonicalType(typed.Type()))
		default:
			return declarationSet{}, "", fmt.Errorf("unsupported exported object %s (%T)", name, object)
		}
	}
	sort.Strings(declarations.types)
	sort.Strings(declarations.constants)
	sort.Strings(declarations.functions)
	sort.Strings(declarations.variables)
	sort.Strings(api)
	digest := sha256.Sum256([]byte(strings.Join(api, "\n") + "\n"))
	return declarations, hex.EncodeToString(digest[:]), nil
}

func typeParameterCount(typ types.Type) int {
	switch typed := typ.(type) {
	case *types.Named:
		return typed.TypeParams().Len()
	case *types.Alias:
		return typed.TypeParams().Len()
	default:
		return 0
	}
}

func exportedMethods(owner string, typ types.Type) []string {
	seen := make(map[string]struct{})
	var methods []string
	for _, candidate := range []types.Type{typ, types.NewPointer(typ)} {
		set := types.NewMethodSet(candidate)
		for index := 0; index < set.Len(); index++ {
			method := set.At(index).Obj()
			if !method.Exported() {
				continue
			}
			entry := "method " + owner + "." + method.Name() + " " + canonicalType(method.Type())
			if _, exists := seen[entry]; exists {
				continue
			}
			seen[entry] = struct{}{}
			methods = append(methods, entry)
		}
	}
	sort.Strings(methods)
	return methods
}

func canonicalType(typ types.Type) string {
	return types.TypeString(typ, func(pkg *types.Package) string { return pkg.Path() })
}

func emitSection(output *strings.Builder, heading, keyword string, names []string) {
	if len(names) == 0 {
		return
	}
	fmt.Fprintf(output, "\n// %s\n", heading)
	for _, name := range names {
		fmt.Fprintf(output, "%s %s = upstream.%s\n", keyword, name, name)
	}
}

func writeAtomic(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create generated output directory: %w", err)
	}
	temporary, err := os.CreateTemp(filepath.Dir(path), ".shimgen-*")
	if err != nil {
		return fmt.Errorf("create temporary generated shim: %w", err)
	}
	temporaryPath := temporary.Name()
	defer os.Remove(temporaryPath)
	if err := temporary.Chmod(0o644); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(data); err != nil {
		temporary.Close()
		return fmt.Errorf("write generated shim: %w", err)
	}
	if err := temporary.Close(); err != nil {
		return fmt.Errorf("close generated shim: %w", err)
	}
	if err := os.Rename(temporaryPath, path); err != nil {
		return fmt.Errorf("install generated shim: %w", err)
	}
	return nil
}
